window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f21cef826ba5640f"]={"versions": [{"id": "FIG-f21cef826ba5640f", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm / Metamodell-Instanzdiagramm auf Ebene des MOF-/UML2-Metamodells im Kontext der AUTOSAR XML-Modell-Persistenzregeln (<em>Model Persistence Rules for XML</em>). Es visualisiert die metamodellierte Repräsentation einer Kompositionsbeziehung (<em>aggregation = composite</em>) zwischen zwei Klassen mittels einer expliziten Eigenschaftsinstanz (<code>:Property</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert drei Metaklassen-Instanzen und deren Beziehungen:</p>\n<ul class=\"fig-list\"><li>Metaklasse <code>:Class</code> mit Attribut <code>name = A</code> (Container-Klasse).\n</li><li>Metaklasse <code>:Class</code> mit Attribut <code>name = C</code> (Typ der aggregierten Instanzen bzw. Kind-Klasse).\n</li><li>Metaklasse <code>:Property</code> als Instanz-Attributspezifikation mit Attributwerten:\n<ul class=\"fig-list\"><li><code>aggregation = composite</code>\n</li><li><code>upper = unbounded</code>\n</li><li><code>lower = 0</code>\n</li><li><code>name = theC</code>\n</li></ul>\n</li><li>Kompositionsbeziehung (<code>+ownedAttribute</code>) mit ausgefüllter Raute von <code>:Class</code> (<code>name = A</code>) zur Instanz <code>:Property</code>.\n</li><li>Gerichtete Assoziation / Referenz (<code>+type</code>) von <code>:Property</code> zur Zielklasse <code>:Class</code> (<code>name = C</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablauf- oder Sequenzpfade. Es beschreibt die strukturelle Definition und Eigentümerschaft eines zusammengesetzten Attributs (<code>theC</code>) innerhalb des Modells.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Referenz für die XML-Serialisierung und -Persistenz von AUTOSAR-Modellen: Ein Attribut mit <code>aggregation = composite</code>, Multiplizität <code>0..*</code> (<code>lower = 0</code>, <code>upper = unbounded</code>) und Namen <code>theC</code> wird in XML als eingebettetes Kindelement unterhalb des XML-Tags der übergeordneten Klasse <code>A</code> serialisiert, wobei jedes Element den Typ <code>C</code> instanziiert.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c7bc87a776e2a60e", "releases": ["R3.0.7", "R3.1.5", "R3.2.3", "R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm / Metamodell-Instanzdiagramm auf Ebene des MOF-/UML2-Metamodells im Kontext der AUTOSAR XML-Modell-Persistenzregeln (<em>Model Persistence Rules for XML</em>). Es visualisiert die metamodellierte Repräsentation einer Kompositionsbeziehung (<em>aggregation = composite</em>) zwischen zwei Klassen mittels einer expliziten Eigenschaftsinstanz (<code>:Property</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert drei Metaklassen-Instanzen und deren Beziehungen:</p>\n<ul class=\"fig-list\"><li>Metaklasse <code>:Class</code> mit Attribut <code>name = A</code> (Container-Klasse).\n</li><li>Metaklasse <code>:Class</code> mit Attribut <code>name = C</code> (Typ der aggregierten Instanzen bzw. Kind-Klasse).\n</li><li>Metaklasse <code>:Property</code> als Instanz-Attributspezifikation mit Attributwerten:\n<ul class=\"fig-list\"><li><code>aggregation = composite</code>\n</li><li><code>upper = unbounded</code>\n</li><li><code>lower = 0</code>\n</li><li><code>name = theC</code>\n</li></ul>\n</li><li>Kompositionsbeziehung (<code>+ownedAttribute</code>) mit ausgefüllter Raute von <code>:Class</code> (<code>name = A</code>) zur Instanz <code>:Property</code>.\n</li><li>Gerichtete Assoziation / Referenz (<code>+type</code>) von <code>:Property</code> zur Zielklasse <code>:Class</code> (<code>name = C</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablauf- oder Sequenzpfade. Es beschreibt die strukturelle Definition und Eigentümerschaft eines zusammengesetzten Attributs (<code>theC</code>) innerhalb des Modells.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Referenz für die XML-Serialisierung und -Persistenz von AUTOSAR-Modellen: Ein Attribut mit <code>aggregation = composite</code>, Multiplizität <code>0..*</code> (<code>lower = 0</code>, <code>upper = unbounded</code>) und Namen <code>theC</code> wird in XML als eingebettetes Kindelement unterhalb des XML-Tags der übergeordneten Klasse <code>A</code> serialisiert, wobei jedes Element den Typ <code>C</code> instanziiert.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-f21cef826ba5640f", "to": "FIG-c7bc87a776e2a60e", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
